<?php

/**
 * Chess Diagram to FEN Position Detector - Common Library
 *
 * Detects chess positions from 8x8 diagram images (such as those generated by
 * https://endgame.md/builder/diagram/) and outputs the standard FEN piece placement string.
 *
 * Architecture:
 *   Square-level multi-class classifier evaluated across all 64 squares:
 *   68 Inputs -> 48 Hidden (Tanh) -> 24 Hidden (Tanh) -> 13 Outputs (Sigmoid)
 *   Total Trainable Weights: (68 * 48) + (48 * 24) + (24 * 13) = 3,264 + 1,152 + 312 = 4,728.
 *
 * 13 Square Classes:
 *   0: '.' (empty)
 *   1..6:  'P', 'N', 'B', 'R', 'Q', 'K' (White pieces)
 *   7..12: 'p', 'n', 'b', 'r', 'q', 'k' (Black pieces)
 *
 * @package NiNa\Examples\ChessFEN
 */

require_once __DIR__ . '/../../src/autoload.php';

use mc\nina\Cell;
use mc\nina\Layer;
use mc\nina\Network;
use mc\nina\activation\Tanh;
use mc\nina\activation\Sigmoid;
use mc\nina\initializer\XavierInitializer;

const CHESS_INPUT_SIZE = 68;
const CHESS_NUM_CLASSES = 13;

/**
 * Returns the 13 class symbols (index 0..12).
 *
 * @return array<int, string>
 */
function getChessClasses(): array
{
    return [
        0  => '.',
        1  => 'P',
        2  => 'N',
        3  => 'B',
        4  => 'R',
        5  => 'Q',
        6  => 'K',
        7  => 'p',
        8  => 'n',
        9  => 'b',
        10 => 'r',
        11 => 'q',
        12 => 'k',
    ];
}

/**
 * Maps a FEN piece character ('.', 'P'..'k') to its class index (0..12).
 */
function chessSymbolToClass(string $symbol): int
{
    static $map = null;
    if ($map === null) {
        $map = array_flip(getChessClasses());
    }
    if (!isset($map[$symbol])) {
        throw new InvalidArgumentException("Unknown chess square symbol: '{$symbol}'");
    }
    return $map[$symbol];
}

/**
 * Builds the 68 -> 48 -> 24 -> 13 neural network for square classification.
 *
 * @param array<int> $hiddenSizes Default [48, 24]
 * @return Network
 */
function createChessFenNetwork(array $hiddenSizes = [48, 24]): Network
{
    $layers = [];
    $prevSize = CHESS_INPUT_SIZE;

    foreach ($hiddenSizes as $idx => $size) {
        $cells = [];
        for ($i = 0; $i < $size; $i++) {
            $cells[] = Cell::Create("h{$idx}_{$i}", $prevSize, 0.0, new Tanh());
        }
        $layers[] = new Layer("hidden_" . ($idx + 1), $cells);
        $prevSize = $size;
    }

    $outputCells = [];
    $classes = getChessClasses();
    for ($c = 0; $c < CHESS_NUM_CLASSES; $c++) {
        $label = $classes[$c] === '.' ? 'empty' : $classes[$c];
        $outputCells[] = Cell::Create("out_{$c}_{$label}", $prevSize, 0.0, new Sigmoid());
    }
    $layers[] = new Layer("output_layer", $outputCells);

    $network = new Network("chess_fen_classifier", $layers);
    $network->initializeWeights(new XavierInitializer());

    return $network;
}

/**
 * Builds an endgame.md diagram URL for a given FEN string and options.
 */
function buildEndgameDiagramUrl(
    string $fen,
    int $size = 30,
    string $style = 'alpha',
    string $color = 'black',
    bool $solid = false,
    bool $double = false
): string {
    $fenBoard = explode(' ', trim($fen))[0];
    $solidStr = $solid ? 'true' : 'false';
    $doubleStr = $double ? 'true' : 'false';
    return "https://endgame.md/builder/diagram/?fen={$fenBoard}&size={$size}&style={$style}&color={$color}&solid={$solidStr}&double={$doubleStr}";
}

/**
 * Loads a GD image resource from a local file path or HTTP/HTTPS URL.
 *
 * @param string $source File path or URL
 * @return \GdImage
 */
function loadChessDiagramImage(string $source): \GdImage
{
    if (!extension_loaded('gd')) {
        throw new RuntimeException("The PHP 'gd' extension is required to process chess diagram images.");
    }

    if (preg_match('/^https?:\/\//i', $source)) {
        $ctx = stream_context_create([
            'http' => [
                'timeout' => 15,
                'user_agent' => 'NiNa-ChessFEN-Detector/1.0',
            ],
            'ssl' => [
                'verify_peer' => false,
                'verify_peer_name' => false,
            ],
        ]);
        $raw = @file_get_contents($source, false, $ctx);
        if ($raw === false || strlen($raw) === 0) {
            throw new RuntimeException("Failed to download diagram from URL: {$source}");
        }
        $img = @imagecreatefromstring($raw);
        if ($img === false) {
            throw new RuntimeException("Failed to decode image data from URL: {$source}");
        }
        return $img;
    }

    if (!file_exists($source)) {
        throw new RuntimeException("Diagram file not found: {$source}");
    }

    $raw = file_get_contents($source);
    if ($raw === false) {
        throw new RuntimeException("Failed to read diagram file: {$source}");
    }

    $img = @imagecreatefromstring($raw);
    if ($img === false) {
        throw new RuntimeException("Unsupported or corrupted image file: {$source}");
    }

    return $img;
}

/**
 * Detects the inner 8x8 board bounding box [offsetX, offsetY, boardWidth, boardHeight, squareSize]
 * inside a diagram image (handles single/double borders automatically).
 *
 * @param \GdImage $img
 * @param int $expectedSquareSize Expected square size in pixels (e.g. 30)
 * @return array{offset_x: int, offset_y: int, square_size: int}
 */
function detectBoardGeometry(\GdImage $img, int $expectedSquareSize = 30): array
{
    $width = imagesx($img);
    $height = imagesy($img);

    $boardPixels = 8 * $expectedSquareSize;
    if ($width >= $boardPixels && ($width - $boardPixels) <= 24) {
        $offsetX = intdiv($width - $boardPixels, 2);
        $offsetY = intdiv($height - $boardPixels, 2);
        return [
            'offset_x' => $offsetX,
            'offset_y' => $offsetY,
            'square_size' => $expectedSquareSize,
        ];
    }

    // Fallback: estimate square size from image width
    $estimatedSquare = intdiv($width, 8);
    $boardPixels = 8 * $estimatedSquare;
    return [
        'offset_x' => intdiv($width - $boardPixels, 2),
        'offset_y' => intdiv($height - $boardPixels, 2),
        'square_size' => $estimatedSquare,
    ];
}

/**
 * Extracts a 2D grayscale array [0..255] of size $squareSize x $squareSize for square ($row, $col).
 *
 * @param \GdImage $img
 * @param int $row 0..7 (0 = rank 8, 7 = rank 1)
 * @param int $col 0..7 (0 = file a, 7 = file h)
 * @param array{offset_x: int, offset_y: int, square_size: int} $geom
 * @return array<int, array<int, float>>
 */
function extractSquarePixels(\GdImage $img, int $row, int $col, array $geom): array
{
    $size = $geom['square_size'];
    $startX = $geom['offset_x'] + $col * $size;
    $startY = $geom['offset_y'] + $row * $size;

    $patch = [];
    for ($y = 0; $y < $size; $y++) {
        $line = [];
        for ($x = 0; $x < $size; $x++) {
            $rgb = imagecolorat($img, $startX + $x, $startY + $y);
            $r = ($rgb >> 16) & 0xFF;
            $g = ($rgb >> 8) & 0xFF;
            $b = $rgb & 0xFF;
            // Perceived luminance in [0..255]
            $line[] = 0.299 * $r + 0.587 * $g + 0.114 * $b;
        }
        $patch[] = $line;
    }

    return $patch;
}

/**
 * Extracts a 68-dimensional normalized feature vector in [0.0, 1.0] from a square pixel patch.
 *
 * Uses scanline contour filling on the piece-ink mask (lum < 75):
 *   1. Thresholding at lum < 75 isolates pure piece ink (0 pixels on both empty light squares
 *      and empty diagonally-hatched dark squares, where background lum >= 86).
 *   2. Filling between the leftmost and rightmost ink pixels on each row reconstructs the solid
 *      2D silhouette S(x, y) for both hollow White pieces and solid Black pieces.
 *
 * Feature Layout (68 features):
 *   - f[0..35]  (36): 6x6 spatial grid of the reconstructed 2D piece silhouette S(x, y)
 *   - f[36..47] (12): 12 horizontal row-width profiles of S(x, y) (2px bands across 24x24 inner box)
 *   - f[48..59] (12): 12 vertical column-height profiles of S(x, y) (2px bands across 24x24 inner box)
 *   - f[60..67]  (8): Piece color fill ratio, silhouette area, inner white detail ratio,
 *                     crown segment complexity, bbox height, bbox width, asymmetry, and bias=1.0
 *
 * @param array<int, array<int, float>> $patch 2D pixel luminance array [0..255]
 * @param int $row Board row (0..7)
 * @param int $col Board col (0..7)
 * @return array<float> 68 floats in [0.0, 1.0]
 */
function extractSquareFeatures(array $patch, int $row, int $col): array
{
    $size = count($patch);
    $margin = 2;                      // 2px margin on 30x30 square -> 26x26 inner box
    $innerSize = $size - 2 * $margin; // 26
    $inkThreshold = 75.0;

    // Count total piece-ink pixels (lum < 75) in the inner 26x26 region
    // Empty squares have 0, White pieces have 60..125, Black pieces have 185..295
    $totalInk = 0;
    for ($y = $margin; $y < $size - $margin; $y++) {
        for ($x = $margin; $x < $size - $margin; $x++) {
            if ($patch[$y][$x] < $inkThreshold) {
                $totalInk++;
            }
        }
    }

    if ($totalInk < 15) {
        // Empty square: all spatial features 0.0, empty indicator = 1.0, bias = 1.0
        $empty = array_fill(0, CHESS_INPUT_SIZE, 0.0);
        $empty[60] = 1.0; // Empty flag
        $empty[67] = 1.0; // Bias
        return $empty;
    }

    // Polarity: +1.0 for White piece (outline ink < 155), -1.0 for Black piece (solid ink >= 155)
    $polarity = ($totalInk < 155) ? 1.0 : -1.0;

    // 1. 7x7 spatial piece-ink grid over the 26x26 inner region (49 features: f[0..48])
    $gridDim = 7;
    $cellSpan = $innerSize / $gridDim;
    $rawGrid = [];
    $maxCell = 0.001;

    for ($gy = 0; $gy < $gridDim; $gy++) {
        for ($gx = 0; $gx < $gridDim; $gx++) {
            $y0 = $margin + (int)floor($gy * $cellSpan);
            $y1 = $margin + (int)floor(($gy + 1) * $cellSpan);
            $x0 = $margin + (int)floor($gx * $cellSpan);
            $x1 = $margin + (int)floor(($gx + 1) * $cellSpan);

            $ink = 0.0;
            $cnt = 0;
            for ($y = $y0; $y < $y1; $y++) {
                for ($x = $x0; $x < $x1; $x++) {
                    if ($patch[$y][$x] < $inkThreshold) {
                        $ink += 1.0;
                    }
                    $cnt++;
                }
            }
            $val = $cnt > 0 ? ($ink / $cnt) : 0.0;
            $rawGrid[] = $val;
            if ($val > $maxCell) {
                $maxCell = $val;
            }
        }
    }

    $features = [];
    foreach ($rawGrid as $val) {
        // Contrast-normalized signed spatial density in [-1.0, +1.0]
        $features[] = $polarity * ($val / $maxCell);
    }

    // 2. 6 Horizontal band profiles (f[49..54]) & 6 Vertical band profiles (f[55..60]) = 12 features
    $numBands = 6;
    $bandSpan = $innerSize / $numBands;
    $hBands = [];
    $maxH = 0.001;
    for ($by = 0; $by < $numBands; $by++) {
        $y0 = $margin + (int)floor($by * $bandSpan);
        $y1 = max($y0 + 1, $margin + (int)floor(($by + 1) * $bandSpan));
        $ink = 0.0;
        $tot = 0;
        for ($y = $y0; $y < $y1; $y++) {
            for ($x = $margin; $x < $size - $margin; $x++) {
                if ($patch[$y][$x] < $inkThreshold) {
                    $ink += 1.0;
                }
                $tot++;
            }
        }
        $val = $tot > 0 ? ($ink / $tot) : 0.0;
        $hBands[] = $val;
        if ($val > $maxH) $maxH = $val;
    }

    $vBands = [];
    $maxV = 0.001;
    for ($bx = 0; $bx < $numBands; $bx++) {
        $x0 = $margin + (int)floor($bx * $bandSpan);
        $x1 = max($x0 + 1, $margin + (int)floor(($bx + 1) * $bandSpan));
        $ink = 0.0;
        $tot = 0;
        for ($y = $margin; $y < $size - $margin; $y++) {
            for ($x = $x0; $x < $x1; $x++) {
                if ($patch[$y][$x] < $inkThreshold) {
                    $ink += 1.0;
                }
                $tot++;
            }
        }
        $val = $tot > 0 ? ($ink / $tot) : 0.0;
        $vBands[] = $val;
        if ($val > $maxV) $maxV = $val;
    }

    // Add 6 H-bands (f[49..54]) and 5 V-bands (f[55..59]) = 11 profile features
    foreach ($hBands as $val) {
        $features[] = $polarity * ($val / $maxH);
    }
    for ($i = 0; $i < 5; $i++) {
        $features[] = $polarity * ($vBands[$i] / $maxV);
    }

    // 3. Global descriptors (8 features: f[60..67])
    $minX = $size;
    $maxX = 0;
    $minY = $size;
    $maxY = 0;
    $crownTransitions = 0;
    $crownEnd = $margin + (int)round($innerSize * 0.42);
    $asymDiff = 0.0;
    $asymPairs = 0;

    for ($y = $margin; $y < $size - $margin; $y++) {
        $prev = 0;
        for ($x = $margin; $x < $size - $margin; $x++) {
            $cur = ($patch[$y][$x] < $inkThreshold) ? 1 : 0;
            if ($cur === 1) {
                if ($x < $minX) $minX = $x;
                if ($x > $maxX) $maxX = $x;
                if ($y < $minY) $minY = $y;
                if ($y > $maxY) $maxY = $y;
            }
            if ($y < $crownEnd && $cur === 1 && $prev === 0) {
                $crownTransitions++;
            }
            $prev = $cur;

            $mirrorX = $size - 1 - $x;
            if ($x < $mirrorX) {
                $mCur = ($patch[$y][$mirrorX] < $inkThreshold) ? 1 : 0;
                $asymDiff += abs($cur - $mCur);
                $asymPairs++;
            }
        }
    }

    $bboxW = ($maxX >= $minX) ? (($maxX - $minX + 1) / $innerSize) : 0.0;
    $bboxH = ($maxY >= $minY) ? (($maxY - $minY + 1) / $innerSize) : 0.0;
    $asym = $asymPairs > 0 ? min(1.0, ($asymDiff / $asymPairs) * 3.0) : 0.0;

    $features[] = 0.0;                                      // f[60]: Empty indicator (0.0 for occupied)
    $features[] = $polarity;                                // f[61]: Piece color polarity (+1 White, -1 Black)
    $features[] = min(1.0, $totalInk / 300.0);              // f[62]: Normalized total ink mass
    $features[] = min(1.0, $crownTransitions / 20.0);       // f[63]: Crown spike/turret complexity
    $features[] = $bboxH;                                   // f[64]: Normalized piece height
    $features[] = $bboxW;                                   // f[65]: Normalized piece width
    $features[] = $asym;                                    // f[66]: Left-right asymmetry (Knights)
    $features[] = 1.0;                                      // f[67]: Constant bias unit

    return $features;
}

/**
 * Parses a FEN string into an 8x8 array of square symbols ('.', 'P'..'k').
 *
 * @param string $fen Full FEN or board placement part
 * @return array<int, array<int, string>>
 */
function fenToBoardGrid(string $fen): array
{
    $placement = trim(explode(' ', trim($fen))[0]);
    $ranks = explode('/', $placement);
    if (count($ranks) !== 8) {
        throw new InvalidArgumentException("Invalid FEN: expected 8 ranks, got " . count($ranks));
    }

    $grid = [];
    foreach ($ranks as $r => $rankStr) {
        $row = [];
        for ($i = 0; $i < strlen($rankStr); $i++) {
            $ch = $rankStr[$i];
            if (ctype_digit($ch)) {
                $emptyCount = (int)$ch;
                for ($k = 0; $k < $emptyCount; $k++) {
                    $row[] = '.';
                }
            } else {
                $row[] = $ch;
            }
        }
        if (count($row) !== 8) {
            throw new InvalidArgumentException("Invalid FEN rank {$r} ('{$rankStr}'): expected 8 columns, got " . count($row));
        }
        $grid[] = $row;
    }

    return $grid;
}

/**
 * Encodes an 8x8 array of square symbols ('.', 'P'..'k') into a standard FEN placement string.
 *
 * @param array<int, array<int, string>> $grid
 * @return string
 */
function boardGridToFen(array $grid): string
{
    $fenRanks = [];
    for ($r = 0; $r < 8; $r++) {
        $rankStr = '';
        $emptyRun = 0;
        for ($c = 0; $c < 8; $c++) {
            $sym = $grid[$r][$c];
            if ($sym === '.') {
                $emptyRun++;
            } else {
                if ($emptyRun > 0) {
                    $rankStr .= (string)$emptyRun;
                    $emptyRun = 0;
                }
                $rankStr .= $sym;
            }
        }
        if ($emptyRun > 0) {
            $rankStr .= (string)$emptyRun;
        }
        $fenRanks[] = $rankStr;
    }

    return implode('/', $fenRanks);
}

/**
 * Detects the full chess position from a diagram image using the trained network.
 *
 * @param Network $network Trained square classifier network
 * @param \GdImage $img GD image of the chess diagram
 * @param int $squareSize Square size in pixels (default 30)
 * @return array{
 *   fen: string,
 *   grid: array<int, array<int, string>>,
 *   confidences: array<int, array<int, float>>,
 *   mean_confidence: float,
 *   min_confidence: float
 * }
 */
function detectPositionFromDiagram(Network $network, \GdImage $img, int $squareSize = 30): array
{
    $geom = detectBoardGeometry($img, $squareSize);
    $classes = getChessClasses();

    $grid = [];
    $confidences = [];
    $sumConf = 0.0;
    $minConf = 1.0;

    for ($r = 0; $r < 8; $r++) {
        $rowSyms = [];
        $rowConfs = [];
        for ($c = 0; $c < 8; $c++) {
            $patch = extractSquarePixels($img, $r, $c, $geom);
            $features = extractSquareFeatures($patch, $r, $c);
            $outputs = $network->Calculate($features);

            $bestClass = 0;
            $bestScore = -1.0;
            foreach ($outputs as $idx => $score) {
                if ($score > $bestScore) {
                    $bestScore = $score;
                    $bestClass = (int)$idx;
                }
            }

            $rowSyms[] = $classes[$bestClass];
            $rowConfs[] = $bestScore;
            $sumConf += $bestScore;
            if ($bestScore < $minConf) {
                $minConf = $bestScore;
            }
        }
        $grid[] = $rowSyms;
        $confidences[] = $rowConfs;
    }

    return [
        'fen' => boardGridToFen($grid),
        'grid' => $grid,
        'confidences' => $confidences,
        'mean_confidence' => $sumConf / 64.0,
        'min_confidence' => $minConf,
    ];
}

/**
 * Renders an 8x8 board grid as an ASCII / Unicode chessboard for terminal output.
 *
 * @param array<int, array<int, string>> $grid
 * @return string
 */
function renderChessboardAscii(array $grid): string
{
    $out = "    +------------------------+\n";
    for ($r = 0; $r < 8; $r++) {
        $rank = 8 - $r;
        $out .= "  {$rank} |";
        for ($c = 0; $c < 8; $c++) {
            $sym = $grid[$r][$c];
            if ($sym === '.') {
                $cell = (($r + $c) % 2 === 1) ? ' · ' : '   ';
            } else {
                $cell = " {$sym} ";
            }
            $out .= $cell;
        }
        $out .= "|\n";
    }
    $out .= "    +------------------------+\n";
    $out .= "      a  b  c  d  e  f  g  h\n";
    return $out;
}
